def can_orient_graph(n, edges):
    # Build the adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize visited array
    visited = [False] * (n + 1)

    def dfs(node, parent):
        stack = [(node, None)]
        while stack:
            current, prev = stack.pop()
            if visited[current]:
                return False
            visited[current] = True
            for neighbor in adj_list[current]:
                if neighbor == parent:
                    continue
                if prev is not None and neighbor == prev:
                    return False
                stack.append((neighbor, current))
        return True

    # Check if we can orient the graph without creating paths of length >= 2
    for node in range(1, n + 1):
        if not visited[node]:
            if not dfs(node, None):
                return "NO", []

    # If we reach here, it means we can orient the graph
    orientation = ['0'] * len(edges)
    for i, (u, v) in enumerate(edges):
        if u < v:
            orientation[i] = '0'
        else:
            orientation[i] = '1'

    return "YES", ''.join(orientation)

