    # Topological sort using Kahn's algorithm
    queue = deque([u for u in range(1, n + 1) if in_degree[u] == 0])
    result = []

    while queue:
        u = queue.popleft()
        result.append(u)

        for v in adj_list[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check if all nodes are visited
    if len(result) != n:
        return "NO"

    # Determine the orientation of edges
    orientation = ['0'] * m
    index_map = {u: i for i, u in enumerate(result)}
    for i, (u, v) in enumerate(edges):
        if index_map[u] < index_map[v]:
            orientation[i] = '0'
        else:
            orientation[i] = '1'

    return "YES\n" + ''.join(orientation)

