def tarjan_scc(n, graph):
    index = 0
    indices = [-1] * n
    lowlinks = [-1] * n
    on_stack = [False] * n
    stack = []
    sccs = []

    def strongconnect(node):
        nonlocal index
        indices[node] = index
        lowlinks[node] = index
        index += 1
        stack.append(node)
        on_stack[node] = True

        for neighbor in graph[node]:
            if indices[neighbor] == -1:
                strongconnect(neighbor)
                lowlinks[node] = min(lowlinks[node], lowlinks[neighbor])
            elif on_stack[neighbor]:
                lowlinks[node] = min(lowlinks[node], indices[neighbor])

        if lowlinks[node] == indices[node]:
            scc = []
            while True:
                w = pop_stack(stack)
                on_stack[w] = False
                scc.append(w)
                if w == node:
                    break
            sccs.append(scc)

    for node in range(n):
        if indices[node] == -1:
            strongconnect(node)

    return sccs

