def can_orient_graph(n, edges):
    # Build the adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Find a root node (any node with degree less than n-1 will work)
    root = None
    for node in range(1, n + 1):
        if len(adj_list[node]) < n - 1:
            root = node
            break

    if root is None:
        return "NO"

    # Perform BFS to check if the graph is a tree
    visited = set()
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node in visited:
            return "NO"
        visited.add(node)
        for neighbor in adj_list[node]:
            if neighbor != root:
                queue.append(neighbor)

    if len(visited) != n:
        return "NO"

    # Orient edges
    orientation = ['0'] * len(edges)
    for i, (u, v) in enumerate(edges):
        if u == root:
            orientation[i] = '0'
        elif v == root:
            orientation[i] = '1'

    return "YES\n" + ''.join(orientation)

